require __DIR__.'/../includes/ui.php';requireRole(['guru']);pageStart('Perwalian','Data siswa dan jadwal kelas yang Anda walikan.');
$classes=dbAll('SELECT * FROM kelas WHERE wali_kelas_id=? ORDER BY nama_kelas',[relatedId()]);if(!$classes)echo '<p class="card empty-state">Belum ada penugasan wali kelas.</p>';
foreach($classes as $k){echo '<h2 class="section-title">Kelas '.e($k['nama_kelas']).' · '.e($k['tahun_ajaran']).'</h2>';tableView(['NIS','Nama','Jenis Kelamin','Orang Tua','Nomor HP'],array_map('array_values',dbAll("SELECT s.nis,s.nama_lengkap,s.jenis_kelamin,o.nama,o.nomor_hp FROM siswa s LEFT JOIN orangtua o ON o.id=s.orangtua_id WHERE s.kelas_id=? AND s.status='aktif' ORDER BY s.nama_lengkap",[$k['id']])));tableView(['Hari','Mulai','Selesai','Mapel','Guru'],array_map('array_values',dbAll('SELECT j.hari,j.jam_mulai,j.jam_selesai,j.mata_pelajaran,g.nama FROM jadwal j JOIN guru g ON g.id=j.guru_id WHERE j.kelas_id=? AND j.tahun_ajaran=? ORDER BY j.hari,j.jam_mulai',[$k['id'],$k['tahun_ajaran']])));}pageEnd();
